INF = 1e12
n, s = map(int, input().split())
c = input()
st = []
for i in range(n):
    if c[i] == 'U':
        if s == 1:
            continue
        if st:
            st.pop()
            continue
        s >>= 1
    elif c[i] == 'L':
        if (s << 1) > INF:
            st.append('L')
            continue
        s = s << 1
    else:
        if (s << 1 | 1) > INF:
            st.append('R')
            continue
        s = s << 1 | 1
print(int(s))
